const { World, setWorldConstructor } = require('@cucumber/cucumber');
const { Window } = require('happy-dom');
const fs = require('fs');
const path = require('path');

class AppWorld extends World {
  constructor(options) {
    super(options);
    this.window = null;
    this.document = null;
  }

  async loadApp() {
    const htmlPath = path.resolve(__dirname, '..', '..', 'index.html');
    const html = fs.readFileSync(htmlPath, 'utf-8');
    this.window = new Window({ url: 'http://localhost/' });
    this.document = this.window.document;
    this.document.write(html);
    this.document.close();
  }

  getTodoItems() {
    return Array.from(this.document.querySelectorAll('.todo-list li'));
  }

  getTodoByText(text) {
    return this.getTodoItems().find(li => {
      const label = li.querySelector('label');
      return label && label.textContent.trim() === text;
    });
  }

  getTodoCount() {
    const strong = this.document.querySelector('.todo-count strong');
    return strong ? parseInt(strong.textContent, 10) : 0;
  }

  getTodoCountText() {
    const span = this.document.querySelector('.todo-count');
    return span ? span.textContent.trim() : '';
  }

  async navigateTo(route) {
    this.window.location.hash = route;
    this.window.dispatchEvent(new this.window.Event('hashchange'));
  }

  async reload() {
    const html = this.document.documentElement.outerHTML;
    this.window = new Window({ url: 'http://localhost/' });
    this.document = this.window.document;
    this.document.write(html);
    this.document.close();
  }
}

setWorldConstructor(AppWorld);

const { Given, When, Then } = require('@cucumber/cucumber');

// Helper to create a todo
function createTodo(world, title) {
  const input = world.document.querySelector('.new-todo');
  input.value = title;
  input.dispatchEvent(new world.window.Event('input'));
  input.dispatchEvent(new world.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, bubbles: true }));
}

// Helper to find a todo by text
function findTodo(world, text) {
  return world.getTodoByText(text);
}

// ==================== Given steps ====================

Given('the app is open', async function () {
  await this.loadApp();
});

Given('a todo {string} exists', async function (title) {
  createTodo(this, title);
});

Given('a completed todo {string} exists', async function (title) {
  createTodo(this, title);
  const todo = findTodo(this, title);
  if (todo) {
    const toggle = todo.querySelector('.toggle');
    if (toggle && !toggle.checked) {
      toggle.click();
    }
  }
});

Given('todos {string} and {string} exist', async function (title1, title2) {
  createTodo(this, title1);
  createTodo(this, title2);
});

Given('todos {string}, {string}, and {string} exist', async function (title1, title2, title3) {
  createTodo(this, title1);
  createTodo(this, title2);
  createTodo(this, title3);
});

Given('the todo {string} is completed', async function (title) {
  const todo = findTodo(this, title);
  if (todo) {
    const toggle = todo.querySelector('.toggle');
    if (toggle && !toggle.checked) {
      toggle.click();
    }
  }
});

// ==================== When steps ====================

When('the user types {string} in the new-todo input and presses Enter', async function (text) {
  const input = this.document.querySelector('.new-todo');
  input.value = text;
  input.dispatchEvent(new this.window.Event('input'));
  input.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, bubbles: true }));
});

When('the user clicks the toggle for {string}', async function (title) {
  const todo = findTodo(this, title);
  if (todo) {
    const toggle = todo.querySelector('.toggle');
    if (toggle) toggle.click();
  }
});

When('the user clicks the toggle-all checkbox', async function () {
  const toggleAll = this.document.querySelector('#toggle-all');
  if (toggleAll) toggleAll.click();
});

When('the user clicks the destroy button for {string}', async function (title) {
  const todo = findTodo(this, title);
  if (todo) {
    const destroy = todo.querySelector('.destroy');
    if (destroy) destroy.click();
  }
});

When('the user clicks the clear-completed button', async function () {
  const btn = this.document.querySelector('.clear-completed');
  if (btn) btn.click();
});

When('the user double-clicks the todo {string}', async function (title) {
  const todo = findTodo(this, title);
  if (todo) {
    const label = todo.querySelector('label');
    if (label) {
      const dblclick = new this.window.Event('dblclick', { bubbles: true });
      label.dispatchEvent(dblclick);
    }
  }
});

When('the user types {string} in the edit input', async function (text) {
  const editing = this.document.querySelector('li.editing');
  if (editing) {
    const editInput = editing.querySelector('.edit');
    if (editInput) {
      editInput.value = text;
      editInput.dispatchEvent(new this.window.Event('input'));
    }
  }
});

When('the user presses Enter', async function () {
  const editing = this.document.querySelector('li.editing');
  if (editing) {
    const editInput = editing.querySelector('.edit');
    if (editInput) {
      editInput.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, bubbles: true }));
    }
  }
});

When('the user presses Escape', async function () {
  const editing = this.document.querySelector('li.editing');
  if (editing) {
    const editInput = editing.querySelector('.edit');
    if (editInput) {
      editInput.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Escape', keyCode: 27, bubbles: true }));
    }
  }
});

When('the user clears the edit input', async function () {
  const editing = this.document.querySelector('li.editing');
  if (editing) {
    const editInput = editing.querySelector('.edit');
    if (editInput) {
      editInput.value = '';
      editInput.dispatchEvent(new this.window.Event('input'));
    }
  }
});

When('the user navigates to {string}', async function (route) {
  await this.navigateTo(route);
});

When('the page is reloaded', async function () {
  await this.reload();
});

// ==================== Then steps ====================

Then('a todo {string} appears in the todo list', async function (title) {
  const todo = findTodo(this, title);
  if (!todo) throw new Error(`Todo "${title}" not found in the list`);
});

Then('the todo {string} does not appear in the todo list', async function (title) {
  const todo = findTodo(this, title);
  if (todo) throw new Error(`Todo "${title}" should not be in the list`);
});

Then('a todo {string} appears in the todo list', async function (title) {
  const todo = findTodo(this, title);
  if (!todo) throw new Error(`Todo "${title}" not found in the list`);
});

Then('the todo {string} does not exist', async function (title) {
  const todo = findTodo(this, title);
  if (todo) throw new Error(`Todo "${title}" should not exist`);
});

Then('the new-todo input is empty', async function () {
  const input = this.document.querySelector('.new-todo');
  if (input.value !== '') throw new Error(`New-todo input has value: "${input.value}"`);
});

Then('the todo count shows {string}', async function (expected) {
  const text = this.getTodoCountText();
  if (text !== expected) throw new Error(`Expected count "${expected}", got "${text}"`);
});

Then('the main section is hidden', async function () {
  const main = this.document.querySelector('.main');
  if (main && main.style.display !== 'none' && !main.classList.contains('hidden')) {
    // Check computed style or class
    const isHidden = main.offsetParent === null || main.style.display === 'none';
    if (!isHidden) throw new Error('Main section is visible when it should be hidden');
  }
});

Then('the main section is visible', async function () {
  const main = this.document.querySelector('.main');
  if (!main) throw new Error('Main section not found');
  const isHidden = main.offsetParent === null || main.style.display === 'none';
  if (isHidden) throw new Error('Main section is hidden when it should be visible');
});

Then('the footer is hidden', async function () {
  const footer = this.document.querySelector('.footer');
  if (footer) {
    const isHidden = footer.offsetParent === null || footer.style.display === 'none';
    if (!isHidden) throw new Error('Footer is visible when it should be hidden');
  }
});

Then('the footer is visible', async function () {
  const footer = this.document.querySelector('.footer');
  if (!footer) throw new Error('Footer not found');
  const isHidden = footer.offsetParent === null || footer.style.display === 'none';
  if (isHidden) throw new Error('Footer is hidden when it should be visible');
});

Then('the todo {string} has the class {string}', async function (title, className) {
  const todo = findTodo(this, title);
  if (!todo) throw new Error(`Todo "${title}" not found`);
  if (!todo.classList.contains(className)) {
    throw new Error(`Todo "${title}" does not have class "${className}"`);
  }
});

Then('the todo {string} does not have the class {string}', async function (title, className) {
  const todo = findTodo(this, title);
  if (!todo) throw new Error(`Todo "${title}" not found`);
  if (todo.classList.contains(className)) {
    throw new Error(`Todo "${title}" has class "${className}" when it should not`);
  }
});

Then('the toggle-all checkbox is checked', async function () {
  const toggleAll = this.document.querySelector('#toggle-all');
  if (!toggleAll) throw new Error('Toggle-all checkbox not found');
  if (!toggleAll.checked) throw new Error('Toggle-all checkbox is not checked');
});

Then('the toggle-all checkbox is unchecked', async function () {
  const toggleAll = this.document.querySelector('#toggle-all');
  if (!toggleAll) throw new Error('Toggle-all checkbox not found');
  if (toggleAll.checked) throw new Error('Toggle-all checkbox is checked when it should be unchecked');
});

Then('all todos have the class {string}', async function (className) {
  const todos = this.getTodoItems();
  for (const todo of todos) {
    if (!todo.classList.contains(className)) {
      const label = todo.querySelector('label');
      throw new Error(`Todo "${label?.textContent}" does not have class "${className}"`);
    }
  }
});

Then('the edit input for {string} is focused', async function (title) {
  const todo = findTodo(this, title);
  if (!todo) throw new Error(`Todo "${string}" not found`);
  const editInput = todo.querySelector('.edit');
  if (!editInput) throw new Error('Edit input not found');
  // In happy-dom, check activeElement
  if (this.document.activeElement !== editInput) {
    throw new Error('Edit input is not focused');
  }
});

Then('the clear-completed button is hidden', async function () {
  const btn = this.document.querySelector('.clear-completed');
  if (btn) {
    const isHidden = btn.offsetParent === null || btn.style.display === 'none';
    if (!isHidden) throw new Error('Clear-completed button is visible when it should be hidden');
  }
});

Then('the new-todo input is focused', async function () {
  const input = this.document.querySelector('.new-todo');
  if (!input) throw new Error('New-todo input not found');
  if (this.document.activeElement !== input) {
    throw new Error('New-todo input is not focused');
  }
});

