(function () {
  'use strict';

  var STORAGE_KEY = 'todos-shakedown';
  var todoList = document.querySelector('.todo-list');
  var newTodoInput = document.querySelector('.new-todo');
  var toggleAllCheckbox = document.querySelector('#toggle-all');
  var mainSection = document.querySelector('.main');
  var footer = document.querySelector('.footer');
  var todoCount = document.querySelector('.todo-count');
  var clearCompletedBtn = document.querySelector('.clear-completed');
  var filters = document.querySelectorAll('.filters li a');

  var todos = loadTodos();
  var currentFilter = getFilterFromHash();

  function loadTodos() {
    try {
      var data = localStorage.getItem(STORAGE_KEY);
      return data ? JSON.parse(data) : [];
    } catch (e) {
      return [];
    }
  }

  function saveTodos() {
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
    } catch (e) {}
  }

  function getFilterFromHash() {
    var hash = window.location.hash || '#/';
    if (hash === '#/active') return 'active';
    if (hash === '#/completed') return 'completed';
    return 'all';
  }

  function createTodo(title) {
    var trimmed = title.trim();
    if (!trimmed) return null;
    var todo = {
      id: Date.now() + Math.random(),
      title: trimmed,
      completed: false
    };
    todos.push(todo);
    saveTodos();
    return todo;
  }

  function deleteTodo(id) {
    todos = todos.filter(function (t) { return t.id !== id; });
    saveTodos();
  }

  function toggleTodo(id) {
    var todo = todos.find(function (t) { return t.id === id; });
    if (todo) {
      todo.completed = !todo.completed;
      saveTodos();
    }
  }

  function toggleAll() {
    var allCompleted = todos.every(function (t) { return t.completed; });
    todos.forEach(function (t) { t.completed = !allCompleted; });
    saveTodos();
  }

  function editTodo(id, newTitle) {
    var trimmed = newTitle.trim();
    if (!trimmed) {
      deleteTodo(id);
      return;
    }
    var todo = todos.find(function (t) { return t.id === id; });
    if (todo) {
      todo.title = trimmed;
      saveTodos();
    }
  }

  function clearCompleted() {
    todos = todos.filter(function (t) { return !t.completed; });
    saveTodos();
  }

  function getFilteredTodos() {
    if (currentFilter === 'active') {
      return todos.filter(function (t) { return !t.completed; });
    }
    if (currentFilter === 'completed') {
      return todos.filter(function (t) { return t.completed; });
    }
    return todos.slice();
  }

  function render() {
    todoList.innerHTML = '';
    var filtered = getFilteredTodos();

    filtered.forEach(function (todo) {
      var li = document.createElement('li');
      li.dataset.id = todo.id;

      if (todo.completed) {
        li.classList.add('completed');
      }

      var viewDiv = document.createElement('div');
      viewDiv.className = 'view';

      var checkbox = document.createElement('input');
      checkbox.className = 'toggle';
      checkbox.type = 'checkbox';
      checkbox.checked = todo.completed;

      var label = document.createElement('label');
      label.textContent = todo.title;

      var destroyBtn = document.createElement('button');
      destroyBtn.className = 'destroy';

      viewDiv.appendChild(checkbox);
      viewDiv.appendChild(label);
      viewDiv.appendChild(destroyBtn);

      var editInput = document.createElement('input');
      editInput.className = 'edit';
      editInput.value = todo.title;

      li.appendChild(viewDiv);
      li.appendChild(editInput);
      todoList.appendChild(li);
    });

    updateUI();
  }

  function updateUI() {
    var activeCount = todos.filter(function (t) { return !t.completed; }).length;
    var completedCount = todos.filter(function (t) { return t.completed; }).length;

    // Update count
    todoCount.innerHTML = '<strong>' + activeCount + '</strong> ' +
      (activeCount === 1 ? 'item' : 'items') + ' left';

    // Show/hide main and footer
    if (todos.length === 0) {
      mainSection.style.display = 'none';
      footer.style.display = 'none';
    } else {
      mainSection.style.display = '';
      footer.style.display = '';
    }

    // Update toggle-all
    toggleAllCheckbox.checked = todos.length > 0 && activeCount === 0;

    // Update clear-completed
    clearCompletedBtn.style.display = completedCount === 0 ? 'none' : '';

    // Update filter links
    filters.forEach(function (a) {
      var filterName = a.getAttribute('href').replace('#/', '') || 'all';
      if (filterName === currentFilter) {
        a.classList.add('selected');
      } else {
        a.classList.remove('selected');
      }
    });
  }

  // Event: new todo input
  newTodoInput.addEventListener('keydown', function (e) {
    if (e.key === 'Enter' || e.keyCode === 13) {
      var title = newTodoInput.value;
      if (createTodo(title)) {
        newTodoInput.value = '';
        render();
      }
    }
  });

  // Event: todo list interactions (delegation)
  todoList.addEventListener('click', function (e) {
    var target = e.target;
    var li = target.closest('li');
    if (!li) return;
    var id = parseFloat(li.dataset.id);

    if (target.classList.contains('toggle')) {
      toggleTodo(id);
      render();
    } else if (target.classList.contains('destroy')) {
      deleteTodo(id);
      render();
    }
  });

  // Event: toggle-all
  toggleAllCheckbox.addEventListener('click', function () {
    toggleAll();
    render();
  });

  // Event: clear-completed
  clearCompletedBtn.addEventListener('click', function () {
    clearCompleted();
    render();
  });

  // Event: double-click to edit
  todoList.addEventListener('dblclick', function (e) {
    var target = e.target;
    if (target.tagName !== 'LABEL') return;
    var li = target.closest('li');
    if (!li) return;
    li.classList.add('editing');
    var editInput = li.querySelector('.edit');
    if (editInput) {
      editInput.focus();
    }
  });

  // Event: edit input interactions
  todoList.addEventListener('keydown', function (e) {
    var target = e.target;
    if (!target.classList.contains('edit')) return;
    var li = target.closest('li');
    if (!li) return;
    var id = parseFloat(li.dataset.id);

    if (e.key === 'Enter' || e.keyCode === 13) {
      editTodo(id, target.value);
      li.classList.remove('editing');
      render();
    } else if (e.key === 'Escape' || e.keyCode === 27) {
      li.classList.remove('editing');
      var todo = todos.find(function (t) { return t.id === id; });
      if (todo) {
        target.value = todo.title;
      }
      render();
    }
  });

  // Event: edit input blur
  todoList.addEventListener('focusout', function (e) {
    var target = e.target;
    if (!target.classList.contains('edit')) return;
    var li = target.closest('li');
    if (!li) return;
    if (!li.classList.contains('editing')) return;
    var id = parseFloat(li.dataset.id);
    editTodo(id, target.value);
    li.classList.remove('editing');
    render();
  });

  // Event: hash change (routing)
  window.addEventListener('hashchange', function () {
    currentFilter = getFilterFromHash();
    render();
  });

  // Initial render
  render();
})();

